// grabient kY4mpDazO-mUuu_fuLqXU49dvVP6
// https://grabient.com/kY4mpDazO-mUuu_fuLqXU49dvVP6?style=silk
// the silk, the palette dyed into folded cloth, as GLSL ES 3.00, the WebGL page's shaders
//
// Each frame is one pass over the canvas: the folds' rings tested by squared distance, a pixel in a ring's band
// reading the valley's and the crest's profiles across it, then the dye's three rows at the pixel's place along the
// dye's line, lerp(lerp(dyed, shade, valley), light, crest). The tables are baked once a palette; a frame sets only
// the rings' middles. The uniforms' values are the page's.

// ==== Pass 1: the silk ==== target: the canvas, W x H, one triangle over it (vertex ids 0 to 2, no attributes) | inputs: T, the dye (32 x 3, RGBA8, linear, clamp to edge; rows dyed, shade, light), S, the profiles (65 x 1, RG16F, linear, clamp to edge; valley, crest)
#version 300 es
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}
#version 300 es
precision highp float;
precision highp int;
/* D: the dye's line as a texel coordinate, u = dot(p, D.xy) + D.z; D.w the canvas's height (p is y down) */
uniform vec4 D;
/* F[i]: ring i's centre (px, y down) and its profile's texel coordinate, x = distance * F.z + F.w; G[i]: its band's
   squared radii, inner and outer */
uniform vec4 F[8];
uniform vec2 G[8];
uniform int N;
/* S: the profiles, 65 x 1 RG16F (valley, crest); T: the palette, 32 x 3 RGBA8 (rows base, shade, lift) */
uniform sampler2D S;
uniform sampler2D T;
out vec4 outColor;

void main() {
  vec2 p = vec2(gl_FragCoord.x, D.w - gl_FragCoord.y);
  float tv = 1.0;
  float tc = 1.0;
  for (int i = 0; i < 8; i++) {
    if (i >= N) break;
    vec4 f = F[i];
    vec2 d = p - f.xy;
    float q = dot(d, d);
    if (q > G[i].x && q < G[i].y) {
      vec2 a = textureLod(S, vec2(sqrt(q) * f.z + f.w, 0.5), 0.0).rg;
      tv -= tv * a.r;
      tc -= tc * a.g;
    }
  }
  float u = dot(p, D.xy) + D.z;
  vec3 b = textureLod(T, vec2(u, 1.0 / 6.0), 0.0).rgb;
  vec3 s = textureLod(T, vec2(u, 0.5), 0.0).rgb;
  vec3 l = textureLod(T, vec2(u, 5.0 / 6.0), 0.0).rgb;
  outColor = vec4(mix(mix(b, s, 1.0 - tv), l, 1.0 - tc), 1.0);
}

